<?php
declare(strict_types=1);
require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/ranked.php';require_once __DIR__.'/includes/battle_presentation.php';pv_require_login();
$db=pv_db();$uid=(int)$_SESSION['myid'];$error='';$notice=(string)($_SESSION['ranked_notice']??'');unset($_SESSION['ranked_notice']);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    try{
        pv_require_csrf();$action=(string)($_POST['action']??'challenge');
        if($action==='challenge'){$r=dn_ranked_challenge($db,$uid,(string)($_POST['match_token']??''));$_SESSION['ranked_replay_match']=(int)$r['id'];pv_redirect('battle_arena.php?match='.$r['id']);}
        elseif($action==='refresh'){dn_ranked_ticket($db,$uid,true);pv_redirect('battle_arena.php');}
        elseif($action==='claim'){$r=dn_ranked_claim($db,$uid,(int)($_POST['season_id']??0));$_SESSION['ranked_notice']='Season reward claimed · #'.$r['rank'].' · +'.number_format($r['bits']).' Bits · +'.$r['medals'].' medals';pv_redirect('battle_arena.php');}
        elseif($action==='exchange'){$_SESSION['ranked_notice']=dn_ranked_exchange($db,$uid,(string)($_POST['item_slug']??''),(string)($_POST['request_token']??''));pv_redirect('battle_arena.php#medal-shop');}
        else throw new RuntimeException('Choose an available Battle Park action.');
    }catch(Throwable $e){$error=$e->getMessage();}
}
$profile=dn_ranked_profile($db,$uid);$season=dn_ranked_season();$rank=dn_ranked_position($db,$uid);$party=dn_ranked_team($db,$uid);$ticket=dn_ranked_ticket($db,$uid);$opponent=$ticket?json_decode($ticket['defender_json'],true,512,JSON_THROW_ON_ERROR):null;
$board=dn_rows($db,'SELECT s.*,m.username,m.created_avatar,IF(b.owner_id IS NULL,0,1) is_bot FROM nxt_ranked_seasons s JOIN members m ON m.id=s.owner_id LEFT JOIN nxt_bots b ON b.owner_id=m.id WHERE s.season_id=? AND m.banned=0 ORDER BY s.points DESC,s.wins DESC,s.owner_id LIMIT 25',[$season]);
$history=dn_rows($db,'SELECT r.id,r.attacker_id,r.defender_id,r.result,r.points_before,r.points_after,r.created_at,a.username attacker_name,d.username defender_name FROM nxt_ranked_matches r JOIN members a ON a.id=r.attacker_id JOIN members d ON d.id=r.defender_id WHERE r.attacker_id=? OR r.defender_id=? ORDER BY r.id DESC LIMIT 15',[$uid,$uid]);
$claims=dn_rows($db,'SELECT season_id FROM nxt_ranked_seasons WHERE owner_id=? AND season_id<? AND reward_claimed=0 AND wins+losses+draws>0 ORDER BY season_id DESC LIMIT 10',[$uid,$season]);
$match=null;$requested=max(0,(int)($_GET['match']??0));if($requested)$match=dn_row($db,'SELECT r.*,a.username attacker_name,d.username defender_name FROM nxt_ranked_matches r JOIN members a ON a.id=r.attacker_id JOIN members d ON d.id=r.defender_id WHERE r.id=? AND (r.attacker_id=? OR r.defender_id=?)',[$requested,$uid,$uid]);
$replay=null;$autoplay=false;
if($match){
    $battle=json_decode($match['battle_json'],true,512,JSON_THROW_ON_ERROR);
    $attacking=(int)$match['attacker_id']===$uid;
    $outcome=$attacking?$match['result']:($match['result']==='win'?'loss':($match['result']==='loss'?'win':'draw'));
    $recorded=$battle['presentation']??null;
    if(is_array($recorded)&&is_array($recorded['initial']??null)&&is_array($recorded['events']??null)&&is_array($recorded['final']??null)){
        $autoplay=(int)($_SESSION['ranked_replay_match']??0)===(int)$match['id'];
        $replay=['id'=>'ranked-'.(int)$match['id'],'initial'=>$recorded['initial'],'events'=>$recorded['events'],'final'=>$recorded['final'],'result'=>$outcome,'autoplay'=>$autoplay,'scene'=>'ranked','truncated'=>(bool)($recorded['truncated']??false)];
    }
    if((int)($_SESSION['ranked_replay_match']??0)===(int)$match['id'])unset($_SESSION['ranked_replay_match']);
}
function nxt_ranked_team_view(array $team): void {echo '<div class="bp-team">';foreach($team as $u)echo '<div class="bp-unit"><img src="'.pv_h(pv_static((string)$u['sprite'])).'" alt="'.pv_h((string)$u['name']).'" loading="lazy"><strong>'.pv_h((string)$u['name']).'</strong><span>Lv. '.(int)$u['level'].' · '.pv_h((string)$u['attribute']).'</span></div>';echo '</div>';}
pv_page_start('Battle Park','battle_arena.php',true);
?>
