<div class="bp-match-record" <?php if($replay):?>data-battle-replay data-dawn-managed data-static-base="<?=pv_h(pv_static(''))?>"<?php endif;?>>
<?php if($replay):?>
<section class="bp-card bp-battle-playback" aria-label="Battle replay">
<div class="bp-section-title"><div><span class="pv-eyebrow">BATTLE REPLAY · MATCH #<?=(int)$match['id']?></span><h2><?=pv_h($match['attacker_name'])?> vs <?=pv_h($match['defender_name'])?></h2></div><button type="button" class="bp-secondary" data-battle-replay-start>Replay battle</button></div>
<p class="bp-fine">Watch the recorded battle. Your rewards are already saved; replaying does not spend energy.</p>
<?php dn_battle_arena_view($replay['initial'],['left_label'=>$match['attacker_name'].($attacking?' · You':' · Attacker'),'right_label'=>$match['defender_name'].(!$attacking?' · You':' · Defender'),'mode'=>'ranked']);?>
<?php if($replay['truncated']):?><p class="bp-fine">Highlights shown; the full battle is available in the report below.</p><?php endif;?>
<noscript><p class="bp-fine">Enable JavaScript to watch the animations, or open the battle report below.</p></noscript>
<script type="application/json" class="dn-battle-replay-config"><?=json_encode($replay,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?></script>
</section>
<?php endif;?>
<section class="bp-result bp-result-<?=pv_h($outcome)?>" data-dawn-result="<?=pv_h($outcome)?>" aria-live="polite"><div><span class="pv-eyebrow"><?=$attacking?'ATTACK RESULT':'DEFENSE RESULT'?> · MATCH #<?=(int)$match['id']?></span><h2><?=match($outcome){'win'=>'Victory!','loss'=>'A rival to overcome.',default=>'An even match.'}?></h2><p><?=pv_h($match['attacker_name'])?> vs <?=pv_h($match['defender_name'])?> · <?=(int)$match['rounds']?> rounds</p><?php if($attacking):?><p><strong><?=(int)$match['points_before']?> → <?=(int)$match['points_after']?> points</strong> · +<?=(int)$match['bits_gain']?> Bits · +<?=(int)$match['exp_gain']?> team EXP · +<?=(int)$match['medals_gain']?> medals</p><?php endif;?><p class="bp-restored">Your party is fully restored. Ready for the next battle.</p><?php if(!$replay):?><p class="bp-fine">This match has a text report. Animated replays are available for new player battles.</p><?php endif;?></div><details class="bp-replay"><summary>Open battle report</summary><div class="bp-report-teams"><?php nxt_ranked_team_view(json_decode($match['attacker_json'],true));nxt_ranked_team_view(json_decode($match['defender_json'],true));?></div><ol><?php foreach($battle['log']??[] as $line):?><li><?=pv_h((string)$line)?></li><?php endforeach;?></ol></details></section>
</div>
<?php endif;?>
