<?php if($opponent):?><div class="bp-rival-header"><img src="<?=pv_h(nxt_skin_url((int)$opponent['created_avatar']))?>" alt=""><div><span class="bp-badge <?=$opponent['is_bot']?'is-ai':'is-human'?>"><?=$opponent['is_bot']?'AI TAMER':'PLAYER'?></span><h3><?=pv_h((string)$opponent['username'])?></h3><p>Rank <?=pv_h(dn_ranked_tier((int)$opponent['points']))?> · <?=(int)$opponent['points']?> season points</p></div></div><?php nxt_ranked_team_view($opponent['team']);?><div class="bp-versus"><span></span><b>YOUR ACTIVE TEAM</b><span></span></div><?php nxt_ranked_team_view($party);?><div class="bp-match-actions"><form method="post"><?=pv_csrf_field()?><input type="hidden" name="action" value="challenge"><input type="hidden" name="match_token" value="<?=pv_h($ticket['token'])?>"><button class="pv-button bp-challenge" <?=$profile['energy']<1?'disabled':''?>>Enter battle · 1 energy</button></form><form method="post"><?=pv_csrf_field()?><input type="hidden" name="action" value="refresh"><button class="bp-secondary">Find another rival</button></form></div><p class="bp-fine">Your first three party members attack automatically using their skills. Opponents defend with their saved formation. Everyone starts at full HP and SP.</p>
